.loader-cambridge-old-theme {
                background: rgba(28,160,208,1);
                background: -moz-linear-gradient(top, rgba(28,160,208,1) 0%, rgba(4,127,172,1) 100%);
                background: -webkit-linear-gradient(top, rgba(28,160,208,1) 0%,rgba(4,127,172,1) 100%);
                background: linear-gradient(to bottom, rgba(28,160,208,1) 0%,rgba(4,127,172,1) 100%);
                filter: progid:DXImageTransform.Microsoft.gradient( startColorstr='#1ca0d0', endColorstr='#047fac',GradientType=0 );
            }
            .loader-cambridge-theme {
                background: #41B6E6;
            }
            .loader-fjord-theme {
                background: #fff;
            }
            #loader-container {
                position: fixed;
                top: 50%;
                left: 50%;
                -webkit-transform: translate(-50%, -50%);
                transform: translate(-50%, -50%);
                text-align: center;
                font-family: Arial, sans-serif;
            }
            #loader-img svg {
                width: 80px;
                height: 80px;
            }
            #loader-img svg image {
                height: 100%;
                width: 100%;
                transform-origin: 50%;
                animation-duration: 0.9s;
                animation-iteration-count: infinite;
                animation-name: loaderRotate;
                animation-timing-function: linear;
            }
            @keyframes loaderRotate {
                from { transform: rotate(0); }
                to { transform: rotate(360deg) }
            }


                #loader-container .error-message {
                    color: #951D1D;
                }
                #loader-container a {
                    display: inline-block;
                    color: #fff;
                    background-color: #2E6C96;
                    padding: 8px 20px;
                    font-size: 16px;
                    text-align: center;
                    vertical-align: middle;
                    cursor: pointer;
                    border: 1px #2E6C96 solid;
                    padding: 10px 40px;
                    border-radius: 4px;
                    margin-top: 16px;
                    text-decoration: none;
                }
                #loader-container a:hover {
                    background-color: #22506f;
                    border-color: #204a67;
                }
